-- Australia Community Worker profile.
-- Exact current occupation: OSCA 411232 Community Support Worker; Community Worker and Community Services Worker are alternative titles.
-- ABS correspondence maps this current occupation to ANZSCO 411512, but there is no clean aligned Australian JSA labour series for the current role.

update ingest.occupations_au
set shortage_rating = null, on_csol = false, median_salary_aud = null,
    confidence = 'official-classification-osl-reviewed',
    source_name = 'ABS OSCA 2024 v1.0 + ABS correspondence + JSA 2025 OSL + reviewed CSOL snapshot',
    source_url = 'https://www.abs.gov.au/statistics/classifications/osca-occupation-standard-classification-australia/2024-version-1-0/browse-classification/4/41/411/4112/411232',
    last_verified = '2026-08-09', anzsco_v13 = '411512'
where anzsco_code = '411232' and occupation_en = 'Community Support Worker';

update public.courses_au set official_course_url = 'https://www.torrens.edu.au/courses/health/bachelor-of-community-services', official_url_status = 'verified', official_url_checked_at = now(), official_url_source = 'Provider current international course page, verified 2026-08-09' where institution_id = 'torrens-university' and course_code = '111741F';
update public.courses_au set official_course_url = 'https://www.tafensw.edu.au/international/courses/diploma-of-community-services--CHC52025', official_url_status = 'verified', official_url_checked_at = now(), official_url_source = 'TAFE NSW International current course page, CRICOS 118878K, verified 2026-08-09', duration_years = 1.0 where institution_id = 'tafe-nsw' and course_code = '118878K';

insert into public.country_occupation_profiles (profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at)
values ('AU:community-worker','AU','community-worker','Community Support Worker','OSCA','2024 v1.0','4112','AUD',false,null,null,'profile_ready','2026-08-09',now())
on conflict (profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();

